#' Pig
#'
#' Draws a pig.
#'
#' @param data .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$pig} \tab \tab \tab \tab \tab an svg \cr
#' }
#'
#' @export
pig <- function(
    data) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pig requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- pigOptions$new()

    analysis <- pigClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}
